  const line = {
    sku: 'STICKER',
    name: 'Sticker sheet',
    qty: 1000,
    unitPrice: 50,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 50000);
});

test('invoiceTotals returns subtotal and total for single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 5,
        unitPrice: 8500,
        vatRate: 21,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, total: 42500 });
});

